using System;
using System.Linq;
using UnityEngine;
public static class RoadMapAuthoringOperationsTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static RoadMapLane Lane(string id,float x,float z,float dx,float dz,string source="road"){return new RoadMapLane{id=id,sourceId=source,roadName="Road",fromNode=id+":a",toNode=id+":b",points=new[]{new MapPoint{x=x,z=z},new MapPoint{x=x+dx,z=z+dz}},heights=new[]{0f,.2f}};}
 public static void Run(){
  var a=Lane("a",0,0,100,0);var b=Lane("b",100,0,0,100);var d=new RoadMapDocument{lanes=new[]{a,b}};
  string join=RoadMapAuthoringOperations.Connect(d,"a","b",-1);Check(a.next.Contains(join)&&d.lanes.First(l=>l.id==join).next.SequenceEqual(new[]{"b"}),"Connection chain missing");
  RoadMapAuthoringOperations.SetTurn(d,"a",-1,false);Check(!a.next.Contains(join),"Turn prohibition retained connection");RoadMapAuthoringOperations.SetTurn(d,"a",-1,true);Check(a.next.Contains(join),"Turn enable did not restore compatible join");
  RoadMapAuthoringOperations.ReverseLane(d,"a");Check(a.points[0].x==100&&a.heights[0]==.2f&&a.fromNode=="a:b"&&a.next.Length==0,"Reverse geometry/topology invalid");
  a=Lane("a",0,0,100,0);var opposite=Lane("opposite",100,4,-100,0);var far=Lane("far",100,400,-100,0);var cross=Lane("cross",50,-50,0,100);var unrelated=Lane("other",100,8,-100,0,"other");unrelated.roadName="Other";d=new RoadMapDocument{lanes=new[]{a,opposite,far,cross,unrelated}};
  Check(RoadMapAuthoringOperations.OpposingLanes(d,"a").SequenceEqual(new[]{"opposite"}),"One way includes remote, perpendicular or unrelated road");RoadMapAuthoringOperations.SetOneWay(d,"a");Check(opposite.disabled&&!far.disabled&&!cross.disabled&&!unrelated.disabled&&!a.disabled,"One way changed unrelated lanes");
  RoadMapAuthoringOperations.AddPoint(d,"a",0);Check(a.points.Length==3&&a.heights.Length==3,"Point insert failed");RoadMapAuthoringOperations.MovePoint(d,"a",1,new Vector3(51,.4f,2));Check(a.points[1].x==51&&a.heights[1]==.4f,"Point move lost height");RoadMapAuthoringOperations.DeletePoint(d,"a",1);Check(a.points.Length==2,"Point delete failed");
  var baseDoc=d.Copy();string copy=RoadMapAuthoringOperations.DuplicateLane(d,"a");Check(d.lanes.Any(l=>l.id==copy),"Duplicate missing");string f=RoadMapAuthoringOperations.CreateFacility(d,"sign","방향 안내",Vector3.zero,"a");RoadMapAuthoringOperations.SnapFacility(d,f);Check(d.facilities.First().x==100,"Facility snap failed");RoadMapAuthoringOperations.DeleteFacility(d,f);Check(d.facilities.Length==0,"Facility delete failed");
  a.ruleId="junction";baseDoc=d.Copy();RoadMapAuthoringOperations.DeleteLane(d,"a");RoadMapAuthoringOperations.RestoreJunction(d,baseDoc,"junction");Check(!d.lanes.First(l=>l.id=="a").disabled,"Junction restore failed");
  a=Lane("split",0,0,100,0);b=Lane("exit",100,0,0,50);a.toNode=b.fromNode;a.next=new[]{b.id};b.turn=-1;d=new RoadMapDocument{lanes=new[]{a,b}};RoadMapAuthoringOperations.AddPoint(d,"split",0);string tail=RoadMapAuthoringOperations.SplitLane(d,"split",1);Check(a.next.SequenceEqual(new[]{tail})&&d.lanes.First(l=>l.id==tail).next.SequenceEqual(new[]{b.id}),"Split lost outgoing chain");
  a=Lane("pocket-source",0,0,100,0);b=Lane("left",100,0,0,30);b.turn=-1;a.next=new[]{b.id};d=new RoadMapDocument{lanes=new[]{a,b}};string pocket=RoadMapAuthoringOperations.Pocket(d,a.id);Check(a.next.Contains(pocket)&&d.lanes.First(l=>l.id==pocket).next.Length==1,"Pocket connections missing");
  string mark=RoadMapAuthoringOperations.CreateFacility(d,"crosswalk","안내",Vector3.zero,pocket);string signal=RoadMapAuthoringOperations.CreateFacility(d,"pedestrianSignal","안내",Vector3.zero);d.facilities.First(fac=>fac.id==signal).targetId=mark;d.signals=new[]{new RoadMapSignalProgram{groups=new[]{new RoadMapSignalGroup{laneIds=new[]{pocket},crosswalkId=mark}}}};RoadMapAuthoringOperations.DeleteLane(d,pocket);Check(!d.facilities.Any(fac=>fac.id==mark||fac.id==signal)&&d.signals.Length==0,"Deletion left dependent references");
  MapCatalog.LockedRegion="eungye";MapCatalog.Load();var baseline=RoadMapRuntime.Baseline;d=RoadMapDocument.Create(baseline);a=d.lanes.First(l=>!l.disabled&&l.next.Any(n=>d.lanes.Any(next=>next.id==n&&next.turn==-1&&next.change==0)));RoadMapAuthoringOperations.SetTurn(d,a.id,-1,false);var composed=RoadMapComposer.Compose(baseline,d);Check(composed.hdEdges.First(l=>l.id==a.id).next.All(n=>composed.hdEdges[n].turn!=-1||composed.hdEdges[n].change!=0),"Composed turn arrow retained forbidden movement");RoadMapAuthoringOperations.SetTurn(d,a.id,-1,true);string signId=RoadMapAuthoringOperations.CreateFacility(d,"sign","좌회전 금지",Vector3.zero,a.id);d.facilities.First(fac=>fac.id==signId).rule=true;composed=RoadMapComposer.Compose(baseline,d);Check(composed.hdEdges.First(l=>l.id==a.id).next.All(n=>composed.hdEdges[n].turn!=-1),"Composed sign rule did not restrict movement");
  RunLineage();
  Debug.Log("ROAD_MAP_AUTHORING_OPERATIONS_TESTS_OK");
 }
 static MapData SplitBaseline(){return new MapData{mapId="synthetic-split",width=200,depth=200,roads=new MapRoad[0],buildings=new MapBuilding[0],targets=new MapTarget[0],areas=new MapArea[0],landmarks=new MapLandmark[0],junctionRules=new HybridJunctionRule[0],hdMarks=new HdMark[0],hdTrials=new HdTrialCase[0],hdSignals=new MapPoint[0],hdEdges=new[]{new HdEdge{id="original:한글/lane",sourceId="road",sourceOffset=1000,fromNode="start",toNode="end",points=new[]{new MapPoint{x=10,z=10},new MapPoint{x=60,z=10},new MapPoint{x=110,z=10}},next=new int[0]}},stops=new[]{new MapStop{graphStop=true,laneEdge=0,laneAt=20},new MapStop{graphStop=true,laneEdge=0,laneAt=50},new MapStop{graphStop=true,laneEdge=0,laneAt=80}}};}
 static void RunLineage(){
  var baseline=SplitBaseline();var d=RoadMapDocument.Create(baseline);string original=d.lanes[0].id;
  Check(typeof(RoadMapLane).GetField("originId")==null&&!d.ToJson().Contains("\"originId\""),"Canonical schema changed");
  d.facilities=new[]{new RoadMapFacility{id="speed",kind="sign",type="제한속도",rule=true,laneId=original,startAt=20,endAt=90,speed=20},new RoadMapFacility{id="turn",kind="sign",type="좌회전 금지",laneId=original}};
  d.signals=new[]{new RoadMapSignalProgram{groups=new[]{new RoadMapSignalGroup{laneIds=new[]{original}}}}};
  string tail=RoadMapAuthoringOperations.SplitLane(d,original,1);Check(RoadMapAuthoringOperations.Origin(d.lanes.First(l=>l.id==tail))==original,"Unicode lineage decode failed");
  Check(d.facilities.Any(f=>f.id=="speed"&&f.laneId==original&&f.startAt==20&&f.endAt==50)&&d.facilities.Any(f=>f.type=="제한속도"&&f.laneId==tail&&f.startAt==0&&f.endAt==40),"Crossing speed range not split");Check(d.facilities.First(f=>f.id=="turn").laneId==tail&&d.signals[0].groups[0].laneIds.SequenceEqual(new[]{tail}),"Terminal rules not moved to tail");
  d.signals=new RoadMapSignalProgram[0];var composed=RoadMapComposer.Compose(baseline,d);Check(composed.hdEdges[composed.stops[0].laneEdge].id==original&&composed.stops[0].laneAt==20,"Head stop changed");Check(composed.hdEdges[composed.stops[1].laneEdge].id==tail&&Mathf.Abs(composed.stops[1].laneAt)<.001f,"Exact split boundary not downstream");Check(composed.hdEdges[composed.stops[2].laneEdge].id==tail&&Mathf.Abs(composed.stops[2].laneAt-30)<.001f,"Tail stop not remapped");
  var full=d.Copy();full.scene=new ProjectMapScene{objects=new[]{new ProjectMapObject{id="service",kind="parking",laneId=original,laneAt=80}}};RoadMapAuthoringOperations.RemapServiceBindings(full);Check(full.scene.objects[0].laneId==tail&&Mathf.Abs(full.scene.objects[0].laneAt-30)<.001f,"Service remap failed");RoadMapAuthoringOperations.RemapServiceBindings(full);Check(Mathf.Abs(full.scene.objects[0].laneAt-30)<.001f,"Service remap not idempotent");
  RoadMapAuthoringOperations.AddPoint(d,tail,0);string last=RoadMapAuthoringOperations.SplitLane(d,tail,1);Check(RoadMapAuthoringOperations.Origin(d.lanes.First(l=>l.id==last))==original,"Repeated split lost origin");composed=RoadMapComposer.Compose(baseline,d);Check(composed.hdEdges[composed.stops[2].laneEdge].id==last&&Mathf.Abs(composed.stops[2].laneAt-5)<.001f,"Repeated stop remap failed");Check(d.facilities.Any(f=>f.type=="제한속도"&&f.laneId==last&&f.startAt==0&&Mathf.Abs(f.endAt-15)<.001f),"Repeated speed remap failed");
  full.lanes=d.Copy().lanes;RoadMapAuthoringOperations.RemapServiceBindings(full);Check(full.scene.objects[0].laneId==last&&Mathf.Abs(full.scene.objects[0].laneAt-5)<.001f,"Repeated service remap failed");bool rejected=false;try{RoadMapAuthoringOperations.ReverseLane(d,last);}catch(InvalidOperationException){rejected=true;}Check(rejected,"Split lineage reverse silently accepted");
  d.lanes.First(l=>l.id==last).disabled=true;rejected=false;try{RoadMapComposer.Compose(baseline,d);}catch(InvalidOperationException){rejected=true;}Check(rejected,"Deleted stop lineage silently accepted");
  baseline=SplitBaseline();d=RoadMapDocument.Create(baseline);var source=d.lanes[0];var left=Lane("left-exit",110,10,0,40);left.fromNode=source.toNode;left.turn=-1;source.next=new[]{left.id};d.lanes=d.lanes.Concat(new[]{left}).ToArray();string pocket=RoadMapAuthoringOperations.Pocket(d,source.id);composed=RoadMapComposer.Compose(baseline,d);Check(composed.hdEdges[composed.stops[2].laneEdge].id!=pocket&&RoadMapAuthoringOperations.Origin(d.lanes[composed.stops[2].laneEdge])==source.id&&Mathf.Abs(composed.stops[2].laneAt-35)<.001f,"Pocket captured baseline stop instead of straight tail");
  var signalDoc=new RoadMapDocument{lanes=new[]{Lane("lane-bound",0,0,100,0)},signals=new[]{new RoadMapSignalProgram{junctionId="bound",groups=new[]{new RoadMapSignalGroup{id="specific",laneIds=new[]{"lane-bound"}},new RoadMapSignalGroup{id="wildcard"}},stages=new[]{new RoadMapStage{groups=new[]{"specific","wildcard"}}}}}};RoadMapAuthoringOperations.DeleteLane(signalDoc,"lane-bound");Check(signalDoc.signals.Length==1&&signalDoc.signals[0].groups.Length==1&&signalDoc.signals[0].groups[0].id=="wildcard"&&signalDoc.signals[0].stages[0].groups.SequenceEqual(new[]{"wildcard"}),"Deleting explicit signal lane broadened group to wildcard");
  d.facilities=new[]{new RoadMapFacility{id="crossing",kind="crosswalk",junctionId="j"},new RoadMapFacility{id="head",kind="pedestrianSignal",junctionId="j",groupId="g",targetId="crossing"}};d.signals=new[]{new RoadMapSignalProgram{junctionId="j",groups=new[]{new RoadMapSignalGroup{id="g",pedestrian=true,crosswalkId="crossing"}},stages=new[]{new RoadMapStage{groups=new[]{"g"}}}}};RoadMapAuthoringOperations.DeleteFacility(d,"crossing");Check(d.signals.Length==0&&d.facilities.Length==0,"Empty program/head cleanup failed");
 }

}
